	}
	if msg.Err != nil {
		log.Printf("INFO [oci_resources] tag meta unavailable for %s at %s: %v", msg.Repo, msg.RegistryURL, msg.Err)
		return m, nil
	}
	if msg.Meta != nil {
		m.registryBrowser.SetMultiTagsMeta(msg.EntryKey, msg.Meta)
	}
	return m, nil
}

// handleRegistryPullRequested admits a browser pull as a job and puts the user
// where they can watch it: the Images tab, browser closed (§3.60).
