func TestAPrefixedRegistryBrowsesAndPullsTheSameRepository(t *testing.T) {
	var asked string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		asked = r.URL.Path
		_, _ = w.Write([]byte(`{"tags":["21"]}`))
	}))
